Fix errors in this Unity test code.

Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_appendf_resize_failure(void) {
    // Setup: create a valid buffer
    buffer_t *buf = buffer_new_with_size(8);
    TEST_ASSERT_NOT_NULL(buf);
    helper_assert_buffer_data_equals(buf, "");
    helper_assert_buffer_length(buf, 0);

    // Prepare format string and argument
    const char *fmt = "Hello %s!";
    const char *name = "World";

    // Calculate how many allocations before the buffer_resize realloc
    // buffer_new_with_size(8): 2 allocations (struct + data)
    // buffer_appendf will call buffer_resize, which calls realloc (3rd allocation)
    malloc_fail_after(2); // Fail the 3rd allocation (the realloc in buffer_resize)

    // Test: buffer_appendf should fail due to allocation failure
    int ret = buffer_appendf(buf, fmt, name);
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // Buffer should remain unchanged
    helper_assert_buffer_data_equals(buf, "");
    helper_assert_buffer_length(buf, 0);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_appendf_resize_failure);
    return UNITY_END();
}

